const days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const today = days[new Date().getDay()];

const avail = ($input.first().json.records || []).filter(r => r.fields.day_of_week === today);
const rooms = ($input.all()[1]?.json?.records || []);

let issues = [];
let coverage = [];

for (const room of rooms) {
  const rf = room.fields;
  const roomName = rf.room_name;
  const roomWords = roomName.split(' ');

  // Count staff qualified for this room
  const qualified = avail.filter(a => {
    const q = a.fields.rooms_qualified || '';
    return q.toLowerCase().includes(roomName.toLowerCase()) ||
           q.toLowerCase().includes(roomWords[0].toLowerCase()) ||
           q.toLowerCase().includes('all rooms');
  });

  const onCallQualified = qualified.filter(a => a.fields.is_on_call);
  const assigned = qualified.filter(a => !a.fields.is_on_call);

  coverage.push({
    room: roomName,
    enrolled: rf.current_enrolled,
    max: rf.max_children,
    ratio: rf.staff_child_ratio,
    min_staff: rf.min_staff,
    assigned_count: assigned.length,
    oncall_count: onCallQualified.length,
    ok: assigned.length >= rf.min_staff
  });

  if (assigned.length < rf.min_staff) {
    issues.push(`⚠ ${roomName}: ${assigned.length}/${rf.min_staff} staff assigned (${rf.current_enrolled} enrolled, ${rf.staff_child_ratio})`);
    if (onCallQualified.length > 0) {
      issues.push(`  💡 On-call available: ${onCallQualified.map(a => `Staff #${a.fields.staff}`).join(', ')}`);
    }
  }
}

const summary = issues.length > 0
  ? `📊 *Staffing Alert — ${today}*\n\n${issues.join('\n')}\n\nAll rooms: ${coverage.map(c => `${c.room} ${c.ok ? '✓' : '⚠'}`).join(', ')}`
  : `📊 *Staffing — ${today}*\n\n${coverage.map(c => `✓ ${c.room}: ${c.assigned_count} staff, ${c.enrolled}/${c.max} enrolled`).join('\n')}`;

return [{json: {summary, coverage, issues, issue_count: issues.length, today}}];

const data = $input.first().json;

if (data.issue_count === 0) {
  return [{json: {notify: false, message: data.summary}}];
}

const message = data.summary +
  `\n\nUse /callout <room> in the Telegram bot to find substitutes.`;

return [{json: {notify: true, message}}];
